/// CONSTRUCT-008: a default plan generated by Ordo from the timer decision
/// records constructs through the unchanged engine. Its stated layout is the
/// engine's own output and nothing else, and the generated F# is the
/// compiled golden source (and pilot 01's B1 output) apart from the header
/// line, which names the plan digest.
module Ordo.Construction.Tests.DefaultPlanConstructionTests

open System.IO
open Xunit
open Ordo.Core.ConstructionPlan
open Ordo.Core.ConstructionPlanWire
open Ordo.Core.ConstructionDecisions
open Ordo.Core.ConstructionDefaultPlan
open Ordo.Construction.Artifacts
open Ordo.Construction.Construction
open Ordo.Construction.Tests.Fixtures

let private records () =
    File.ReadAllText(Path.Combine(repositoryRoot, "tests", "fixtures", "construction", "time-entry-timer", "construction-decisions.json"))
    |> readDecisionRecords |> ok "decisions"

let private defaultPlan vocabulary = generateDefaultPlan (prepared timer) (records ()) vocabulary |> ok "default plan"

let private vocabularies = [ ConstructionVocabulary.Version1; ConstructionVocabulary.Version2 ]

/// Everything after the first line, which carries generator and plan digest.
let private body (content: string) = content.Substring(content.IndexOf '\n' + 1)

let private source (c: Construction) (suffix: string) =
    c.Artifacts |> List.find (fun a -> a.Path.EndsWith suffix) |> _.Content

[<Fact>]
let ``the default plan's generated layout is exactly the engine's artifact paths`` () =
    for vocabulary in vocabularies do
        let p = defaultPlan vocabulary
        let c = construct p.ValidatedPlan |> ok "construct"
        Assert.Equal<string list>(c.Artifacts |> List.map _.Path, p.GeneratedLayout)
        Assert.Equal(p.PlanDigest, c.PlanDigest)
        for path in p.GeneratedLayout do
            Assert.StartsWith(c.OwnershipRoot, path)

[<Fact>]
let ``without a port record the layout has no orchestration tier, as the engine decides`` () =
    let r = records ()
    let noPorts = { r with Records = r.Records |> List.filter (fun x -> x.NodeId <> "IFC-TIMER-PORTS") }
    let p = generateDefaultPlan (prepared timer) noPorts ConstructionVocabulary.Version2 |> ok "default plan"
    let c = construct p.ValidatedPlan |> ok "construct"
    Assert.Equal<string list>(c.Artifacts |> List.map _.Path, p.GeneratedLayout)
    Assert.DoesNotContain("generated/Timer/Timer.Orchestration.g.fs", p.GeneratedLayout)
    // The port requirements are now uncovered obligations, not invented ports.
    Assert.Equal(2, p.Obligations |> List.filter (fun o -> o.Kind = TypedObligationKind.UncoveredRequirement && o.NodeIds |> List.contains "IFC-TIMER-PORTS") |> List.length)

[<Fact>]
let ``writing a default plan's construction into an empty target creates only the stated layout`` () =
    for vocabulary in vocabularies do
        let p = defaultPlan vocabulary
        let writes = construct p.ValidatedPlan |> ok "construct" |> planWrites Map.empty |> ok "writes"
        Assert.Equal<PlannedWrite list>(p.GeneratedLayout |> List.map Create, writes)

[<Fact>]
let ``the generated F# is the compiled golden source apart from the header line`` () =
    let v1 = defaultPlan ConstructionVocabulary.Version1 |> _.ValidatedPlan |> construct |> ok "construct v1"
    let v2 = defaultPlan ConstructionVocabulary.Version2 |> _.ValidatedPlan |> construct |> ok "construct v2"
    let golden fixture name = File.ReadAllText(goldenPath fixture name)
    for tier in [ "Model"; "Transition"; "Orchestration" ] do
        let suffix = sprintf ".%s.g.fs" tier
        Assert.Equal(body (golden timer (sprintf "generated/Timer/Timer%s" suffix)), body (source v1 suffix))
        let unresolved = golden timerUnresolved (sprintf "generated/TimerUnresolved/TimerUnresolved%s" suffix)
        Assert.Equal((body unresolved).Replace("TimerUnresolved", "Timer"), body (source v2 suffix))
    Assert.StartsWith(GeneratedMarker + "/1 from " + v1.PlanDigest + ">", source v1 ".Model.g.fs")
    Assert.StartsWith(GeneratedMarker + "/2 from " + v2.PlanDigest + ">", source v2 ".Model.g.fs")

[<Fact>]
let ``the default plan constructs the same F# as pilot 01's agent-authored B1 plan`` () =
    let b1 =
        File.ReadAllText(Path.Combine(repositoryRoot, "tests", "fixtures", "construction", "time-entry-timer-pilot-01", "B1.plan.json"))
        |> readPlan |> ok "B1" |> validate (prepared timer) |> ok "validate B1" |> construct |> ok "construct B1"
    let generated = defaultPlan ConstructionVocabulary.Version1 |> _.ValidatedPlan |> construct |> ok "construct"
    for suffix in [ ".Model.g.fs"; ".Transition.g.fs"; ".Orchestration.g.fs" ] do
        Assert.Equal(body (source b1 suffix), body (source generated suffix))
    Assert.Equal<StructuralCheck list>(b1.StructuralChecks, generated.StructuralChecks)
    Assert.Equal<string list>(b1.ExtensionContracts |> List.map _.Name, generated.ExtensionContracts |> List.map _.Name)
